import { shouldRunWorkflowCliTelemetry } from '../../command-ids.js';
import { commandTraceContext } from '../../lib/command-context.js';
import { rawFlagValue, resourceFlags } from '../../lib/flags.js';
import { shouldForceShareTelemetry } from '../../lib/share-definitions.js';
import { setupCliTelemetry } from '../../lib/telemetry-setup.js';
export const CLI_PACKAGE_NAME = '@sanity/workflow-cli';
export function cliPackageVersion(config) {
    return config.plugins.get(CLI_PACKAGE_NAME)?.version;
}
export async function installPrerunTelemetry(args) {
    const { bin, version, commandId, argv, flagDefs, commandTelemetry, env = process.env } = args;
    if (!shouldRunWorkflowCliTelemetry({ bin, commandId })) {
        return;
    }
    await setupCliTelemetry({
        cliVersion: version,
        configPath: rawFlagValue(argv, { name: 'path' }),
        target: {
            projectId: rawFlagValue(argv, { name: 'project-id', char: resourceFlags['project-id'].char }),
            dataset: rawFlagValue(argv, { name: 'dataset', char: resourceFlags.dataset.char }),
        },
        forceSend: shouldForceShareTelemetry({ commandId, argv }),
        context: commandTraceContext({ commandId, argv, flagDefs, commandTelemetry, env }),
        env,
    });
}
const hook = async function ({ config, Command, argv }) {
    await installPrerunTelemetry({
        bin: config.bin,
        version: cliPackageVersion(config),
        commandId: Command?.id,
        argv,
        flagDefs: Command?.flags,
        commandTelemetry: Command?.telemetry,
    });
};
export default hook;
